export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"willingness-willingness-is-readiness-to-enter-and-participate-fully-in-life-and-0213b28d90cd\",\"title\":\"Willingness Willingness is readiness to enter and participate fully in life and living. Find a willing response to each situation. Willingness is doing just what is needed:\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9631],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/05-dbt-distress-tolerance-distress-tolerance-handout-13-willingness-willingness-is-readiness-b2d9c7b33e.json\",\"sha256\":\"b2d9c7b33e4970f4d0126a44d5de171c87e555cfb631e96595e2ca7accc5149b\",\"domain\":\"dbt\",\"bytes\":4846},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/distress-tolerance-handout-13-willingness-willingness-is-readiness-to-enter-and-participate--11e332c37b.json\",\"sha256\":\"11e332c37be3eea4867d5f799bf3f0d15875b21fc5e84124ff29e24d0617ba50\",\"domain\":\"dbt\",\"bytes\":4686}]},\"data\":{\"pages\":[{\"pdf_page\":370,\"book_page\":\"346\",\"text\":\"346\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nDistress Tolerance Handout 13   (Distress Tolerance Worksheets 8, 8a, 10)\\nWillingness\\nWillingness is readiness to enter and participate fully in life and living.\\nFind a willing response to each situation.\\nWillingness is doing just what is needed:\\n\u2022\u2022 In each situation.\\n\u2022\u2022 Wholeheartedly, without dragging your feet.\\nWillingness is listening very carefully to your Wise Mind, and then\\nacting from your Wise Mind.\\nWillingness is acting with awareness that you are connected\\nto the universe (to the stars, people you like and don\u2019t like, the floor,\\netc.).\\nReplace willfulness with willingness.\\n\u2022\u2022 Willfulness is refusing to tolerate the moment.\\n\u2022\u2022 Willfulness is refusing to make changes that are needed.\\n\u2022\u2022 Willfulness is giving up.\\n\u2022\u2022 Willfulness is the opposite of \u201cdoing what works.\u201d\\n\u2022\u2022 Willfulness is trying to fix every situation.\\n\u2022\u2022 Willfulness is insisting on being in control.\\n\u2022\u2022 Willfulness is attachment to \u201cme, me, me\u201d and \u201cwhat I want\\nright now!\u201d\\nWillingness, Step by Step\\n1.\\t Observe the willfulness. Label it. Experience it.\\n2.\\t Radically accept that at this moment you feel (and may be\\nacting) willful. You cannot fight willfulness with willfulness.\\n3.\\t Turn your mind toward acceptance and willingness.\\n4.\\t Try half-smiling and a willing posture.\\n5.\\t When willfulness is immovable, ask, \u201cWhat\u2019s the threat?\u201d\\nSituations where I notice my own:\\nWillfulness:\\nWillingness:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Distress Tolerance Handout 13   (Distress Tolerance Worksheets 8, 8a, 10)\",\"source_pdf_pages\":[370],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/distress_tolerance/handouts/distress_tolerance_handout_13_willingness_willingness_is_readiness_to_enter_and_participate_fully_in.json\",\"item_number\":\"13\",\"full_text\":\"\u00ab\\nDistress Tolerance Handout 13   (Distress Tolerance Worksheets 8, 8a, 10)\\nWillingness\\nWillingness is readiness to enter and participate fully in life and living.\\nFind a willing response to each situation.\\nWillingness is doing just what is needed:\\n\u2022\u2022 In each situation.\\n\u2022\u2022 Wholeheartedly, without dragging your feet.\\nWillingness is listening very carefully to your Wise Mind, and then\\nacting from your Wise Mind.\\nWillingness is acting with awareness that you are connected\\nto the universe (to the stars, people you like and don\u2019t like, the floor,\\netc.).\\nReplace willfulness with willingness.\\n\u2022\u2022 Willfulness is refusing to tolerate the moment.\\n\u2022\u2022 Willfulness is refusing to make changes that are needed.\\n\u2022\u2022 Willfulness is giving up.\\n\u2022\u2022 Willfulness is the opposite of \u201cdoing what works.\u201d\\n\u2022\u2022 Willfulness is trying to fix every situation.\\n\u2022\u2022 Willfulness is insisting on being in control.\\n\u2022\u2022 Willfulness is attachment to \u201cme, me, me\u201d and \u201cwhat I want\\nright now!\u201d\\nWillingness, Step by Step\\n1.\\t Observe the willfulness. Label it. Experience it.\\n2.\\t Radically accept that at this moment you feel (and may be\\nacting) willful. You cannot fight willfulness with willfulness.\\n3.\\t Turn your mind toward acceptance and willingness.\\n4.\\t Try half-smiling and a willing posture.\\n5.\\t When willfulness is immovable, ask, \u201cWhat\u2019s the threat?\u201d\\nSituations where I notice my own:\\nWillfulness:\\nWillingness:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Distress Tolerance Worksheets 8, 8a, 10\"],\"id\":\"distress_tolerance_handout_13\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"346\"],\"title\":\"Willingness Willingness is readiness to enter and participate fully in life and living. Find a willing response to each situation. Willingness is doing just what is needed:\",\"module_category\":\"Distress Tolerance Skills\",\"shared_json_path\":\"shared/05_dbt_distress_tolerance/handouts_json/distress_tolerance_handout_13_willingness_willingness_is_readiness_to_ent_172fdfcb.json\",\"module\":\"Distress Tolerance\",\"keywords\":[\"Find\",\"Willingness\",\"doing\",\"each\",\"enter\",\"fully\",\"just\",\"life\",\"living\",\"needed\",\"participate\",\"readiness\",\"response\",\"situation\",\"what\",\"willing\"]}}");
